INSERT OR REPLACE INTO notes (slug, category, title, content, parent_slug, sort_order, updated_at) VALUES ('Comping/基本节奏', 'guitar', '基本节奏', '<h1>基本节奏</h1><div>&nbsp; &nbsp; 现在我们已经有能力在吉他上任何位置按出任何和弦，我们可以试着开始comping了，刚入门爵士吉他的吉他手们可以从两个最简单的comping节奏学起：Freddie Green rhythm（左）和Charlston rhythm（右）：</div><div><div contenteditable="false" data-resizable="" class="img-light" style="margin: 16px auto; resize: both; max-width: 100%; min-width: 40px; min-height: 20px; text-align: center; width: 391px; height: 181px;"><img src="data:image/png;base64," style="pointer-events: none;"></div><div data-resizable="" class="img-dark" style="display: block; margin: 16px auto; resize: both; max-width: 100%; min-width: 40px; min-height: 20px; height: 181px; width: 378px;"><img src="data:image/png;base64," style="pointer-events: none;"></div></div><div><font color="#cc4444">&nbsp; &nbsp;&nbsp;</font><span style="color: var(--color-text);">在演奏这两个基本节奏的时候，注意左手需要把不演奏的弦都闷掉，右手及时制音，造成一个swing的效果。</span></div>
<p></p>', 'Comping', 0, 1783836246474);
