INSERT OR REPLACE INTO notes (slug, category, title, content, parent_slug, sort_order, updated_at) VALUES ('基础电子元件库/焊接套装', 'synth', '焊接套装', '<h1>焊接套装</h1><div>电烙铁</div><div>锡丝</div><div>松香（或者其他助焊剂）</div><div>铜丝球</div><div>硅胶隔热垫</div><div>斜口钳</div><div>镊子</div><div>吸锡器</div>
